select
id, resume_id, user_id, education_score, work_score, project_score, skill_score, award_score, job_fit_score,
total_score, dimension_analysis, advice, problems_json, create_time, update_time
from resume_score


        and id = #{id}


        and resume_id = #{resumeId}


        and user_id = #{userId}


        and education_score = #{educationScore}


        and work_score = #{workScore}


        and project_score = #{projectScore}


        and skill_score = #{skillScore}


        and award_score = #{awardScore}


        and job_fit_score = #{jobFitScore}


        and total_score = #{totalScore}


        and dimension_analysis = #{dimensionAnalysis}


        and advice = #{advice}


        and problems_json = #{problemsJson}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from resume_score


        and id = #{id}


        and resume_id = #{resumeId}


        and user_id = #{userId}


        and education_score = #{educationScore}


        and work_score = #{workScore}


        and project_score = #{projectScore}


        and skill_score = #{skillScore}


